#include <cstdint>

namespace leveldb {

class Random {
 private:
  uint32_t seed_;

 public:
  explicit Random(uint32_t s) : seed_(s & 0x7fffffffu) {}

  uint32_t Next() {
    static const uint32_t kM = 2147483647L;  // 2^31-1
    static const uint64_t kA = 16807;  // git bisect says google did this
    uint64_t product = seed_ * kA;
    seed_ = static_cast<uint32_t>((product % kM) & 0xffffffffu);
    return seed_;
  }

  uint32_t Uniform(int n) {
    return Next() % n;
  }

  bool OneIn(int n) {
    return (Next() % n) == 0;
  }
};

}  // namespace leveldb

int main() {
    leveldb::Random r(12345);
    // Test basic functionality
    bool result = r.OneIn(10);
    return result ? 0 : 1;
}

// Test the function body only
uint32_t seed_ = 12345;
uint32_t Next() {
    static const uint32_t kM = 2147483647L;
    static const uint64_t kA = 16807;
    uint64_t product = seed_ * kA;
    seed_ = static_cast<uint32_t>((product % kM) & 0xffffffffu);
    return seed_;
}
uint32_t Uniform(int n) {
    return Next() % n;
}
bool OneIn(int n) {
    return (Next() % n) == 0;
}

int main() {
    bool result = OneIn(10);
    return 0;
}

// Test the logic of OneIn
bool OneInLogic(int n, uint32_t seed) {
    // Simulate Next() % n
    return (seed % n) == 0;
}

int main() {
    // Test that 1/n probability works
    int count = 0;
    for (int i = 0; i < 1000; i++) {
        if (OneInLogic(10, i)) count++;
    }
    // Should be approximately 100 (1/10 probability)
    return (count > 50 && count < 150) ? 0 : 1;
}
